@Override
    public void flush() throws IOException
    {
        synchronized (lock)
        {
            output.flush();
        }
    }

@Override
    public void close() throws IOException
    {
        synchronized (lock)
        {
            if (output == null) {
                return ;
            }

            if (state == LAST_WAS_CR_STATE) {
                output.write('\n');
            } else if (state != LAST_WAS_NL_STATE) {
                output.write("\r\n");
            }

            output.write(".\r\n");

            output.flush();
            output = null;
        }
    }

@Override
    public int read() throws IOException
    {
        final int ch;

        if (status == LAST_WAS_NL)
        {
            status = NOTHING_SPECIAL;
            return '\n';
        }

        ch = in.read();

        switch (ch)
        {
        case '\r':
            status = LAST_WAS_CR;
            return '\r';
        case '\n':
            if (status != LAST_WAS_CR)
            {
                status = LAST_WAS_NL;
                return '\r';
            }
            //$FALL-THROUGH$
        default:
            status = NOTHING_SPECIAL;
            return ch;
        }
        // statement not reached
        //return ch;
    }

@Override
    public int read(final byte[] buffer) throws IOException
    {
