        synchronized (lock)
        {
            if ((ch = read()) == -1)
            {
                return -1;
            }

            final int off = offset;

            do
            {
                buffer[offset++] = (char) ch;
            }
            while (--length > 0 && (ch = read()) != -1);

            return offset - off;
        }
    }

